"If a new transaction's description contains the text, it gets that category. The first matching rule wins, and a category you set by hand is never changed.":"אם התיאור של תנועה חדשה מכיל את הטקסט, היא מקבלת את הקטגוריה הזו. הכלל הראשון שמתאים גובר, וקטגוריה שקבעתם ידנית אף פעם לא משתנה.",
"If a new transaction's description contains the text, it gets these tags. Tags are added on top of the category, and a rule can add several. When you add a rule you can also tag the transactions you already have.":"אם התיאור של תנועה חדשה מכיל את הטקסט, היא מקבלת את התגיות האלה. תגיות מתווספות לצד הקטגוריה, וכלל יכול להוסיף כמה תגיות. כשמוסיפים כלל אפשר לתייג גם תנועות שכבר קיימות.",
"If a payment from your bank contains the text, it is the bill of a credit card. It is not counted as spending, because each purchase is already counted on the card.":"אם תשלום מהבנק מכיל את הטקסט, זה חשבון של כרטיס אשראי. הוא לא נספר כהוצאה, כי כל רכישה כבר נספרת בכרטיס.",
"If an income contains the text (in its description or the payer), it is marked as Salary when it has no category yet.":"אם הכנסה מכילה את הטקסט (בתיאור או אצל המשלם), היא מסומנת כמשכורת כשעדיין אין לה קטגוריה.",
