"That jar is empty, so nothing can be taken from it":"הקופה הזו ריקה, אז אי אפשר לקחת ממנה כלום",
"That name is reserved.":"השם הזה שמור.",
"That password is too easy to guess.":"הסיסמה הזאת קלה מדי לניחוש.",
