"The app cannot write to that folder. Pick another one.":"האפליקציה לא יכולה לכתוב לתיקייה הזאת. בחרו אחרת.",
"The app expects this bill based on your past payments.":"האפליקציה מצפה לחשבון הזה לפי התשלומים הקודמים שלכם.",
"The app expects this bill based on your past payments. It is not a transaction yet and is not in the totals. Click to open the bill.":"האפליקציה מצפה לחשבון הזה לפי התשלומים הקודמים שלכם. זו עדיין לא תנועה והיא לא נכללת בסכומים. לחצו כדי לפתוח את החשבון.",
"The app only reads your transactions and balances. It cannot move money.":"האפליקציה רק קוראת תנועות ויתרות. היא לא יכולה להעביר כסף.",
"The app thinks money moved between two of your own accounts. Check it, so it is not counted as spending.":"נראה שכסף עבר בין שני החשבונות שלכם. בדקו שזה נכון, כדי שלא ייספר כהוצאה.",
"The app will expect it again":"האפליקציה תצפה לו שוב",
