"This one was imported before the app started keeping all of the bank's details. The extra details appear the next time this date is read again (for example with Import history).":"הפריט הזה יובא לפני שהאפליקציה התחילה לשמור את כל פרטי הבנק. הפרטים הנוספים יופיעו בפעם הבאה שהתאריך הזה ייקרא שוב (למשל עם ייבוא היסטוריה).",
"This one was imported before the app started keeping all of the bank’s details. The extra details appear the next time this date is read again (for example with Import history).":"הפריט הזה יובא לפני שהאפליקציה התחילה לשמור את כל פרטי הבנק. הפרטים הנוספים יופיעו בפעם הבאה שהתאריך הזה ייקרא שוב (למשל עם ייבוא היסטוריה).",
