"You have no budget here, so the app uses your usual month, the average of your recent months, minus what you have already spent. It is real money in your accounts that you can still spend. What is left at month end can go into jars.":"אין לכם כאן תקציב, ולכן האפליקציה משתמשת בחודש רגיל שלכם, הממוצע של החודשים האחרונים, פחות מה שכבר הוצאתם. זה כסף אמיתי בחשבונות שעוד אפשר להוציא. מה שנשאר בסוף החודש יכול לעבור לקופות.",
